export async function requireProSubscriber() {
  const user = await getAuthenticatedUser();

  if (!user) {
    redirect("/sign-in");
  }

  if (
    !isProSubscriberPlan(
      user.plan,
      user.subscription?.currentPeriodEnd ?? null,
    )
  ) {
